using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
namespace OceanariumFishing.Editor
{
    public static class BoatTravelChecks
    {
        static readonly List<string> log=new();static bool running;static Keyboard keyboard;
        static void Check(bool ok,string message){log.Add((ok?"PASS: ":"FAIL: ")+message);if(!ok)throw new InvalidOperationException(message);}
        static BoatHarbor Harbor=>UnityEngine.Object.FindFirstObjectByType<BoatHarbor>();
        public static void Run(){if(running||!EditorApplication.isPlaying)return;running=true;log.Clear();GameSession.Current.StartCoroutine(Guard());}
        static IEnumerator Guard(){bool pass=true;var iter=Steps();while(true){object value=null;bool next=false;try{next=iter.MoveNext();if(next)value=iter.Current;}catch(Exception e){log.Add(e.ToString());Debug.LogException(e);pass=false;break;}if(!next)break;yield return value;}if(keyboard!=null){InputSystem.RemoveDevice(keyboard);keyboard=null;}File.WriteAllText("Docs/ASTRA_07_TEST_RESULTS.txt",(pass?"PASS ":"FAIL ")+DateTime.UtcNow.ToString("O")+"\n"+string.Join("\n",log));running=false;}
        static IEnumerator Steps()
        {
            var h=Harbor;Check(h&&h.Ready&&h.islandId=="home","Start on existing Home Island");var collection=h.Inventory.Collection;string fish=string.Join("|",collection.kept.Select(f=>f.instanceId+":"+f.ownership+":"+f.tankId).OrderBy(s=>s));string layout=JsonUtility.ToJson(collection.aquarium.layout);string appearance=JsonUtility.ToJson(AppearanceStore.Load());int coins=collection.aquarium.coins;
            var seats=new BoatReadiness();for(int n=0;n<4;n++){seats.Connect("sim"+n);Check(seats.Board("sim"+n,out var seat)&&seat==n,"LOCAL SIMULATION: independent seat "+n);seats.SetReady("sim"+n,true);}seats.Connect("sim4");Check(!seats.Board("sim4",out _),"LOCAL SIMULATION: fifth passenger rejected");Check(!seats.CanDepart,"LOCAL SIMULATION: unboarded active player blocks departure");seats.Disconnect("sim4");Check(seats.CanDepart,"LOCAL SIMULATION: disconnected player no longer blocks departure");seats.SetReady("sim2",false);Check(!seats.CanDepart,"LOCAL SIMULATION: per-player readiness enforced");
            if(!h.Progress.introduced){if(!h.Busy)h.StartCoroutine(h.Introduction());yield return new WaitForSeconds(1);ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_07_FinnArrival.png");yield return new WaitForSeconds(.3f);h.SkipRequested=true;yield return new WaitForSeconds(.3f);}Check(h.Progress.introduced&&!h.Busy,"Arrival skip completes story and restores camera");
            h.Player.Teleport(h.captain.position+Vector3.back);h.Talk();yield return new WaitForSeconds(.4f);ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_07_RepairQuest.png");if(!h.Progress.accepted)Check(h.Accept(),"Accept repair quest");h.CloseDialogue();h.Player.Teleport(h.dockExit.position);if(!h.Progress.inspected)Check(h.Inspect(),"Inspect damaged boat");
            if(!h.Progress.repaired){Check(!h.Repair(),"Cannot repair before materials / proximity validation");foreach(var pickup in UnityEngine.Object.FindObjectsByType<BoatResource>(FindObjectsSortMode.None).OrderBy(p=>p.id)){h.Player.Teleport(pickup.transform.position+Vector3.back*.4f);yield return null;int before=h.Count(pickup.resource);Check(h.Pickup(pickup.id,pickup.resource,pickup.amount),"Collect finite world resource "+pickup.id);Check(h.Count(pickup.resource)==before+pickup.amount,"Resource inventory increment");Check(!h.Pickup(pickup.id,pickup.resource,pickup.amount),"Pickup cannot duplicate");}Check(h.MaterialsReady,"All required materials available without grinding");h.Player.Teleport(h.captain.position+Vector3.back);Check(h.Repair(),"Repair commits quest and consumes materials");yield return new WaitForSeconds(1);h.SkipRequested=true;yield return new WaitForSeconds(.3f);Check(h.Count("driftwood")==0&&h.Count("scrap")==0&&h.Count("rope")==0,"Exact repair resource consumption");}
            Check(h.Progress.repaired&&h.Progress.boatTier==1&&!h.damage.activeSelf&&h.repairedVisual.activeSelf,"Repaired visuals and starter boat tier");Check(!h.Repair(),"Completed repair cannot charge again");Check(!h.PurchaseUpgrade("tier_1",out _),"Future upgrade remains locked");
            for(int trip=0;trip<4;trip++)
            {
                h=Harbor;h.Player.Teleport(h.dockExit.position);Check(h.Board(),"Board existing customized player");yield return new WaitForSeconds(1);Check(h.MapOpen&&h.Readiness.CanDepart&&h.Readiness.Seats.Count==1,"Map opens with one ready passenger");Check(!h.RequestTravel("coral"),"Locked island rejected");if(trip==0){ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_07_WorldMap.png");yield return new WaitForSeconds(.2f);}string next=h.islandId=="home"?"town":"home";Check(h.RequestTravel(next),"Authorized departure to "+next);Check(!h.RequestTravel(next),"Repeated departure request rejected");yield return new WaitForSeconds(trip==0?2:.5f);h.SkipRequested=true;
                float deadline=Time.realtimeSinceStartup+30;while((Harbor==h||!Harbor||!Harbor.Ready)&&Time.realtimeSinceStartup<deadline)yield return null;Check(Harbor&&Harbor!=h&&Harbor.Ready,"Destination scene loads without duplicate services");h=Harbor;yield return new WaitForSeconds(1);h.SkipRequested=true;deadline=Time.realtimeSinceStartup+15;while(h.Busy&&Time.realtimeSinceStartup<deadline)yield return null;
                Check(h.islandId==next&&!h.Busy&&h.Player.enabled&&h.Player.view.enabled,"Arrival skip restores gameplay camera and input");Check(Vector3.Distance(h.Player.transform.position,h.dockExit.position)<1,"Correct harbor arrival spawn");Check(UnityEngine.Object.FindObjectsByType<LocalPlayerController>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<GameSession>(FindObjectsSortMode.None).Length==1,"Exactly one player and one session service");
                if(next=="town"&&trip==0){keyboard=InputSystem.AddDevice<Keyboard>();h.Player.SetViewAngles(0,18);var p=h.Player.transform.position;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.W));yield return new WaitForSeconds(1.2f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;Check(Vector3.Distance(h.Player.transform.position,p)>1,"Town harbor supports physical walking");h.Player.Teleport(new Vector3(0,2,-10));h.Player.SetViewAngles(0,18);yield return new WaitForSeconds(.7f);ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_07_TownIsland.png");yield return new WaitForSeconds(.2f);}
                collection=h.Inventory.Collection;Check(string.Join("|",collection.kept.Select(f=>f.instanceId+":"+f.ownership+":"+f.tankId).OrderBy(s=>s))==fish,"Fish identities and aquarium assignments survive travel");Check(JsonUtility.ToJson(collection.aquarium.layout)==layout,"Museum layout survives travel");Check(collection.aquarium.coins==coins,"Wallet unchanged by free introductory travel");Check(JsonUtility.ToJson(AppearanceStore.Load())==appearance,"Character appearance persists");
            }
            var saved=FishCollectionStore.Load();Check(saved.travel.repaired&&saved.travel.lastIsland=="home"&&string.IsNullOrEmpty(saved.travel.pendingDestination),"Completed travel persisted at safe Home harbor");Check(saved.travel.collected.Distinct().Count()==saved.travel.collected.Count,"Finite pickups retain unique IDs");File.WriteAllText("Temp/ASTRA07_expected.json",JsonUtility.ToJson(saved.travel));h.Player.SetViewAngles(35,18);ScreenCapture.CaptureScreenshot("Docs/Screenshots/ASTRA_07_ReturnHome.png");
        }
        public static void Restart()
        {log.Clear();bool pass=true;try{var h=Harbor;var expected=JsonUtility.FromJson<TravelProgress>(File.ReadAllText("Temp/ASTRA07_expected.json"));Check(h.Progress.repaired&&h.Progress.introduced&&h.Progress.accepted&&h.Progress.inspected,"Repair and story restore in fresh Play Mode");Check(JsonUtility.ToJson(h.Progress)==JsonUtility.ToJson(expected),"Travel progression exactly restored");Check(UnityEngine.Object.FindObjectsByType<BoatResource>(FindObjectsSortMode.None).All(r=>!h.Progress.collected.Contains(r.id)),"Collected resources do not respawn");Check(!h.Busy&&h.Player.enabled,"No interrupted cinematic input lock");Check(UnityEngine.Object.FindFirstObjectByType<AquariumBuilding>().Navigation.Validate(UnityEngine.Object.FindFirstObjectByType<AquariumBuilding>().Layout),"Customized museum routes still valid after return");}catch(Exception e){pass=false;log.Add(e.ToString());}File.WriteAllText("Docs/ASTRA_07_RESTART_RESULTS.txt",(pass?"PASS ":"FAIL ")+DateTime.UtcNow.ToString("O")+"\n"+string.Join("\n",log));}
    }
}
